"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["22822"],{99630(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modelo_formulario.descricao_tamanho","status":422,"titulo":"Descri\xe7\xe3o do modelo de formul\xe1rio excede o tamanho m\xe1ximo"},"descricao":{"codigo":"uniplus.configuracao.modelo_formulario.descricao_tamanho","requisitos":[],"oQueAconteceu":["A `descricao` enviada na cria\xe7\xe3o (`POST /api/configuracao/admin/modelos-formulario`) ou na atualiza\xe7\xe3o (`PUT /api/configuracao/admin/modelos-formulario/{id}`) tem mais de 1000 caracteres, depois de aparados os espa\xe7os nas pontas. A descri\xe7\xe3o \xe9 opcional; em branco ou ausente ela \xe9 aceita.","A recusa vem na lista `errors` da resposta, com `field` igual a `descricao`. As demais recusas do corpo v\xeam na mesma resposta, e nada \xe9 gravado. Na atualiza\xe7\xe3o, a busca do modelo vem antes das valida\xe7\xf5es de dom\xednio do conte\xfado: com um `{id}` que n\xe3o existe, a resposta \xe9 [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado), e n\xe3o esta. S\xf3 a leitura do corpo vem antes da busca: campo n\xe3o anul\xe1vel ausente ou nulo (como `nome`) \xe9 recusado com 400, sem c\xf3digo deste cat\xe1logo, mesmo com `{id}` inexistente."],"comoResolver":["Reduza a descri\xe7\xe3o para at\xe9 1000 caracteres, ou omita-a, e repita o pedido."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modelo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);